"""Check native CPU and worker placement for one Bazel submission."""
from collections import Counter
import hashlib
import json
import os
from pathlib import Path
import re
import struct
import subprocess
import sys
import uuid
import xml.etree.ElementTree as ET
from urllib.parse import unquote, urlparse

import exec_cas as cas


W = Path(os.environ["RUNNER_TEMP"]) / "mixed-native"
S = "afc19c8fdae528d466147ed0aa638714af430eef"
SUBJECTS = {"//test/syscalls:uname_test_runsc_systrap_directfs":
            ("Sanity", "SetNames", "UnprivilegedSetNames", "UnshareUTS")}
CPU = {"amd64": ("x86_64", 62), "arm64": ("aarch64", 183)}
T = {label + "_" + arch: (arch, cases)
     for label, cases in SUBJECTS.items() for arch in CPU}
PATTERNS = W / "syscall-native.targets"
IMAGE = "docker://docker.io/library/ubuntu@sha256:b8b6ee6aa931ecd9d0d952abc34dc0e5f7c6a30c6bb71b079fe399fde0329c02"
BAZEL = [str(W/"bazel"),"--nosystem_rc","--nohome_rc","--host_jvm_args=-Xmx9500m"]
FLAGS = ["--config=source-presubmit-mixed", "--color=no", "--curses=no",
         "--nocache_test_results", "--flaky_test_attempts=1",
         "--modify_execution_info=^TestRunner$=+no-remote-cache"]
HEX = re.compile(r"[a-f0-9]{64}")
PUB = re.compile(r"//[A-Za-z0-9+._/-]*:[A-Za-z0-9+._/-]+")
TERMS = ("conflicting actions","action conflict","attempted to generate the same","generated by these conflicting","no matching toolchains",
         "no matching execution platform","exec format error","no registered executors","resource_exhausted",
         "resource exhausted","deadline exceeded","operation not permitted","no such file or directory",
         "unknown exec group","permission denied","undeclared inclusion","strict dependencies","out of memory","action failed","signal: killed")


def save(name,d):
    raw=json.dumps(d,sort_keys=True,indent=1)
    assert len(raw)<75000 and not re.search(r"(?i)authorization:|x-buildbuddy-api-key|github_pat_|gh[pousr]_[A-Za-z0-9]{20,}",raw)
    if "ACCESS" in os.environ:assert os.environ["ACCESS"] not in raw
    (W/"output"/(name+".json")).write_text(raw+"\n")


def read(name):
    return json.loads((W/"output"/(name+".json")).read_text())


def events(name):
    p=W/(name+".bep")
    if p.exists():
        with p.open() as f:
            for line in f:
                try:yield json.loads(line)
                except ValueError:return


def signal(path):
    words=set()
    if path.exists():
        with path.open(errors="replace") as f:
            for l in f:
                low=l.lower()
                words.update(t for t in TERMS if t in low)
    return sorted(words)


def call(cmd,phase,args,minutes):
    with (W/(phase+".stdout")).open("w") as out,(W/(phase+".log")).open("w") as err:
        secret=["--bazelrc="+str(W/"remote.rc")] if phase=="execute" else []
        return subprocess.run(["timeout","--signal=INT","--kill-after=45s",str(minutes)+"m",*BAZEL,*secret,cmd,*FLAGS,
                "--build_event_json_file="+str(W/(phase+".bep")),*args],stdout=out,stderr=err).returncode


def analyze():
    src=subprocess.check_output(["git","rev-parse","HEAD"],text=True).strip()
    assert src==S
    assert "remote_default_exec_properties=Arch" not in Path(".bazelrc").read_text()
    PATTERNS.write_text("\n".join(T) + "\n")
    opts=["--spawn_strategy=local","--strategy=TestRunner=local","--jobs=4"]
    code=call("test","selection",[*opts,"--target_pattern_file="+str(PATTERNS),"--nobuild","--build_tests_only"],11)
    planned=set()
    for e in events("selection"):
        t=e["id"].get("targetCompleted",{})
        if t and not t.get("aspect") and e.get("aborted",{}).get("reason")=="NO_BUILD":
            planned.add(t["label"])
    r={"source":S,"selection_exit":code,"selected":sorted(t for t in planned if PUB.fullmatch(t)),
        "selection_ok":code==1 and planned==T.keys(),"selection_signals":signal(W/"selection.log"),"eligible":False}
    save("selection",r)
    if not r["selection_ok"]:return
    query = 'mnemonic("^TestRunner$",set(' + ' '.join(T) + '))'
    code=call("aquery","graph",[*opts,"--output=jsonproto","--include_artifacts=false",query],10)
    r.update(graph_exit=code,graph_signals=signal(W/"graph.log"),tests={})
    save("selection",r)
    if code:return
    data=json.loads((W/"graph.stdout").read_text())
    targets={str(t["id"]):t["label"] for t in data["targets"]}
    for a in data.get("actions",[]):
        label=targets[str(a["targetId"])]
        if a["mnemonic"]!="TestRunner" or label not in T:
            continue
        cpu,_=T[label]
        platform=a.get("executionPlatform","").removeprefix("@@")
        isolation={v["key"]:v.get("value","") for v in a.get("executionInfo",[])}.get("workload-isolation-type","oci")
        r["tests"].setdefault(label,[]).append({
            "platform":platform if PUB.fullmatch(platform) else None,
            "isolation":isolation if isolation in ("oci","firecracker") else "other",
            "matches":platform=="//test/rbe:ubuntu_"+cpu and isolation=="firecracker",
        })
    r["eligible"]=r["tests"].keys()==T.keys() and all(
        len(actions)==1 and actions[0]["matches"] for actions in r["tests"].values())
    save("selection",r)


def execute():
    assert read("selection")["eligible"]
    assert PATTERNS.read_text().splitlines()==list(T)
    outputs = "|".join(label[2:].replace(":","/") for label in T)
    code=call("test","execute",["--jobs=55","--keep_going","--remote_download_outputs=minimal",
        "--target_pattern_file="+str(PATTERNS),
        "--remote_download_regex=.*(testlogs/("+outputs+")/test[.](xml|log)|bin/test/runner/setup_container/setup_container|bin/test/syscalls/linux/uname_test)$"],42)
    save("exit",{"source":S,"exit":code,"signals":signal(W/"execute.log")})


def output_log(label, output):
    uri=urlparse(output.get("uri",""))
    d=re.search(r"/(?:blobs|compressed-blobs/zstd)/([a-f0-9]{64})/(\d+)$",uri.path)
    ref=(d[1],int(d[2])) if d else (output.get("digest"),int(output.get("length",0)))
    name=output["name"]
    paths=([Path(unquote(uri.path))] if uri.scheme=="file" else [])
    sub=label[2:].replace(":","/")+"/"+name
    paths.extend(Path("bazel-out").glob("*/testlogs/"+sub))
    for p in paths:
        if p.is_file() and p.stat().st_size<=5*1024*1024:
            raw=p.read_bytes();digest=hashlib.sha256(raw).hexdigest()
            if ref[0] and ref!=(digest,len(raw)):continue
            return raw,digest
    return None,None


def collect():
    r={"source":S,"test_results":{},"errors":[],"builds":{},"summaries":{},"verified":False}
    for e in events("execute"):
        ids=e["id"]
        if "started" in e:r["invocation"]=str(uuid.UUID(e["started"]["uuid"]))
        if "finished" in e:r["bazel_exit"]=int(e["finished"].get("exitCode",{}).get("code",0))
        t=ids.get("targetCompleted",{})
        if t.get("label") in T and not t.get("aspect"):
            r["builds"][t["label"]]=e["completed"].get("success",False) if "completed" in e else None
        if "action" in e and not e["action"].get("success",False) and len(r["errors"])<14:
            own=ids.get("actionCompleted",{}).get("label","")
            typ=e["action"].get("type","")
            uri=e["action"].get("stderr",{}).get("uri","")
            d=re.search(r"/blobs/([a-f0-9]{64})/(\d+)$",uri)
            r["errors"].append({"owner":own if PUB.fullmatch(own) else "dependency","mnemonic":typ if re.fullmatch(r"[a-zA-Z0-9_]+",typ) else "other",
                 "stderr":[d[1],int(d[2])] if d else None})
        label=ids.get("testSummary",{}).get("label","")
        if label in T and "testSummary" in e:r["summaries"][label]=e["testSummary"].get("overallStatus")=="PASSED"
        label=ids.get("testResult",{}).get("label","")
        if label not in T or "testResult" not in e:continue
        t=e["testResult"];info=t.get("executionInfo",{});cpu,expected=T[label]
        row={"passed":t.get("status")=="PASSED","remote":info.get("strategy")=="remote",
             "cached":bool(t.get("cachedLocally") or info.get("cachedRemotely")), "expected":expected}
        r["test_results"].setdefault(label,[]).append(row)
        for o in t.get("testActionOutput",[]):
            if o.get("name") not in ("test.log","test.xml"):continue
            raw,digest=output_log(label,o)
            if not raw:continue
            row[o["name"]+"_sha256"]=digest
            if o["name"] == "test.log":
                row["guest_launch"] = b" in container " in raw and b"-platform systrap" in raw
            if o["name"]=="test.xml":
                try:nodes=list(ET.fromstring(raw).iter("testcase"))
                except ET.ParseError:continue
                counts=Counter();verdict={name:[] for name in expected}; cases=[]; skipped=[]
                for case in nodes:
                    state="passed"
                    if any(case.find(tag) is not None for tag in ("failure","error")):state="failed"
                    elif case.find("skipped") is not None or case.get("status")=="notrun" or case.get("result")=="skipped":state="skipped"
                    counts[state]+=1
                    name=case.get("name","")
                    cases.append((name,state))
                    case_name = re.split(r"[./]", name)[-1]
                    suite = case.get("classname", "") + "/" + name
                    if "UnameTest" in suite and case_name in verdict:
                        verdict[case_name].append(state)
                    if state=="skipped":
                        skipped.append(name if re.fullmatch(r"Test[A-Za-z0-9_./=+-]{1,160}",name) else "other")
                row["skipped_names"]=skipped[:50]
                row["case_status_sha256"]=hashlib.sha256(json.dumps(sorted(cases)).encode()).hexdigest()
                row["cases"]=dict(counts);row["named_verdict"]=verdict
        row["confirmed"] = (
            row["passed"] and row["remote"] and not row["cached"]
            and row.get("named_verdict") == {name: ["passed"] for name in expected}
            and row.get("cases") == {"passed": 4}
            and row.get("guest_launch")
        )
    r["executables"] = {}
    for file in ("test/runner/setup_container/setup_container", "test/syscalls/linux/uname_test"):
        items = []
        for path in sorted(Path("bazel-out").glob("*/bin/" + file)):
            if not path.is_file():
                continue
            with path.open("rb") as stream:
                header = stream.read(20)
                stream.seek(0)
                digest = hashlib.file_digest(stream, "sha256").hexdigest()
            if len(header) == 20 and header[:6] == b"\x7fELF\x02\x01":
                items.append({"sha256": digest, "machine": struct.unpack_from("<H", header, 18)[0]})
        r["executables"][file] = items
    if r["test_results"].keys()==T.keys():
        archives = all({x["machine"] for x in items} == {62, 183} for items in r["executables"].values())
        r["verified"] = r.get("bazel_exit")==0 and archives and all(
            r["builds"].get(t) and r["summaries"].get(t) and len(r["test_results"][t])==1
            and r["test_results"][t][0]["confirmed"] for t in T
        )
    save("test",r)


def platform_fields(message):
    p={}
    for k,v in cas.fields(message):
        if k==1:
            prop=dict(cas.fields(v))
            if 1 in prop and 2 in prop:p[prop[1].decode()]=prop[2].decode()
    return {"cpu":p.get("Arch") if p.get("Arch") in CPU else None,"linux":p.get("OSFamily")=="linux",
        "ubuntu":p.get("container-image")==IMAGE,
        "class":p.get("workload-isolation-type") if p.get("workload-isolation-type") in ("oci","firecracker") else None,
        "root":p.get("dockerUser")=="root","ipv6":p.get("network-enable-ipv6")=="true"}


def service():
    test=read("test"); plan=read("selection")
    assert test["source"]==S and plan["source"]==S and plan["eligible"]
    assert subprocess.check_output(["git","rev-parse","HEAD"],text=True).strip()==S
    # Only this workflow's source-bound BEP can select an invocation. No
    # service request is made for any other product or earlier submission.
    cas.INV=str(uuid.UUID(test["invocation"]))
    r={"source":S,"invocation":cas.INV,"workers":{},"diagnostics":{},"verified":False}
    for label in T:
        try:
            rows=cas.executions(label,"TestRunner")
            assert len(rows)<=15
            for e in rows:
                meta=e["actionDigest"]
                action=dict(cas.fields(cas.blob(meta,128*1024)))
                cmd=list(cas.fields(cas.blob(cas.digest_msg(action[1]),4*1024*1024)))
                args=[v.decode() for t,v in cmd if t==1]
                rep=e.get("executeResponse",{})
                if "result" not in rep:
                    continue
                out=rep["result"]
                if not (any(s.endswith("/test-setup.sh") for s in args) or
                    any(str(f.get("path","")).endswith("/test.cache_status") for f in out.get("outputFiles",[]))):
                    continue
                p=platform_fields(action[10]) if 10 in action else next((platform_fields(v) for t,v in cmd if t==5),{})
                row={"platform":p,"action_sha256":meta["hash"],"exit":out.get("exitCode",0),"rpc":rep.get("status",{}).get("code",0),
                     "cached":bool(rep.get("cachedResult")),"qemu":any("qemu-" in s for s in args)}
                cpu,_=T[label]
                row["matches"]=(p.get("cpu")==cpu and p.get("class")=="firecracker" and p.get("root") and p.get("ipv6") and p.get("linux") and p.get("ubuntu")
                                and not row["cached"] and not row["rpc"] and not row["exit"] and not row["qemu"])
                r["workers"].setdefault(label,[]).append(row)
                save("workers",r)
        except (OSError,ValueError,KeyError,AssertionError,IndexError) as ex:
            r["diagnostics"][label]=type(ex).__name__
            save("workers",r)
    r["verified"]=(test["verified"] and r["workers"].keys()==T.keys() and
        all(len(r["workers"][k])==1 and r["workers"][k][0]["matches"] for k in T))
    save("workers",r)


if __name__=="__main__":
    {"analyze":analyze,"execute":execute,"collect":collect,"service":service}[sys.argv[1]]()
